ROOT:
-- OrderSearch : 条件検索＋ページング（ROW_NUMBER + CTE ＝ SQL 制御方式） -- 全件取得してメモリでページングしない。総件数は OrderSearchCount.xml で別途取得する。 WITH OrderPage AS ( SELECT ROW_NUMBER() OVER (ORDER BY [OrderID] ASC) AS RNUM, [OrderID], [CustomerID], [EmployeeID], [OrderDate], [RequiredDate], [ShippedDate], [ShipVia], [Freight], [ShipName], [ShipAddress], [ShipCity], [ShipRegion], [ShipPostalCode], [ShipCountry] FROM [Orders]
WHERE AND [CustomerID] = @CustomerID AND [EmployeeID] = @EmployeeID AND [ShipVia] = @ShipVia AND [ShipCountry] LIKE @ShipCountry
) SELECT [OrderID], [CustomerID], [EmployeeID], [OrderDate], [RequiredDate], [ShippedDate], [ShipVia], [Freight], [ShipName], [ShipAddress], [ShipCity], [ShipRegion], [ShipPostalCode], [ShipCountry] FROM OrderPage WHERE RNUM BETWEEN @FromRow AND @ToRow ORDER BY RNUM
